('Pumbaa', 'LC-17', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'The First Chapter'), (SELECT id FROM rarities WHERE name = 'Common'), 4, TRUE, '/assets/cards/lorcana_en_set1_17_1897f93c14bb4d6bc0ca397cc24aacc602b30a61.avif', '', '17/204 EN 1', 'characters', '“You gotta put your behind in your past.”', 'Jenna Gray'),
('Rapunzel', 'LC-18', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'The First Chapter'), (SELECT id FROM rarities WHERE name = 'Legendary'), 4, TRUE, '/assets/cards/lorcana_en_set1_18_71f25a859f742e0d2c7cb96fa115542072d77583.avif', '<p>\Gleam and Glow\ When you play this character, remove up to 3 damage from one of your characters. Draw a card for each 1 damage removed this way.</p>', '18/204 EN 1', 'characters', '', 'Jochem Van Gool'),
