('Archimedes', 'LC-36', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'The First Chapter'), (SELECT id FROM rarities WHERE name = 'Common'), 1, TRUE, '/assets/cards/lorcana_en_set1_36_9b4622774b8ed661ffcad97da702922e35e326b1.avif', '', '36/204 EN 1', 'characters', '“Flying is not merely some crude, mechanical process. It is a delicate art. Purely aesthetic. Poetry of motion. And the best way to learn it is to do it!”', 'Kendall Hale'),
('Dr. Facilier', 'LC-37', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'The First Chapter'), (SELECT id FROM rarities WHERE name = 'Rare'), 7, FALSE, '/assets/cards/lorcana_en_set1_37_df8214278bc2ef1790dfeb0a241cc1ec8bd5c693.avif', '<p>&lt;Shift&gt; 5 (You may pay 5 {I} to play this on top of one of your characters named Dr. Facilier.)<br>\Into the Shadows\ Whenever one of your other characters is banished in a challenge, you may return that card to your hand.</p>', '37/204 EN 1', 'characters', '', 'Isaiah Mesq'),
