('Elsa', 'LC-40', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'The First Chapter'), (SELECT id FROM rarities WHERE name = 'Common'), 4, TRUE, '/assets/cards/lorcana_en_set1_40_01dc5bb928054aa2b228f2a1f97910208b36b42b.avif', '', '40/204 EN 1', 'characters', '“I never knew what I was capable of.”', 'Duyen Nguyen / Aubrey Archer'),
