('Happy', 'LC-227', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 5, TRUE, '/assets/cards/lorcana_en_set2_11_02c3b7887d833fee96dabc584973ecf294a01708.avif', '<p>&lt;Support&gt; (Whenever this character quests, you may add their {S} to another chosen character''s {S} this turn.)</p>', '11/204 EN 2', 'characters', 'You couldn''t pick a better friend.', 'Kendall Hale'),
('King Louie', 'LC-228', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Super Rare'), 7, TRUE, '/assets/cards/lorcana_en_set2_12_4f1adf24190f6b87e17af431f81f105198502337.avif', '<p>\Lay it on the Line\ Whenever another character is banished, you may remove up to 2 damage from this character.</p>', '12/204 EN 2', 'characters', '“Cool it, boy. Unwind yourself.”', 'Hadjie Joos'),
('Mickey Mouse', 'LC-229', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Super Rare'), 6, TRUE, '/assets/cards/lorcana_en_set2_13_d18739c5e2057865fb5f134000c8d30c7c8f3409.avif', '<p>\Glad You''re Here!\ Whenever this character quests, you pay 3 {I} less for the next character you play this turn.</p>', '13/204 EN 2', 'characters', '"Come on in—there’s lots to explore."', 'Veronica Di Lorenzo / Livio Cacciatore'),
('Mufasa', 'LC-230', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Legendary'), 5, TRUE, '/assets/cards/lorcana_en_set2_14_65e58dd193dad4bca35c786674adcd24995084eb.avif', '<p>\The Sun Will Set\ When this character is banished, you may reveal the top card of your deck. If it''s a character card, you may play that character for free and they enter play exerted. Otherwise, put it on the top of your deck.</p>', '14/204 EN 2', 'characters', '', 'Stefano Zanchi'),
('Mulan', 'LC-231', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Deep Trouble – Illumineer''s Quest'), (SELECT id FROM rarities WHERE name = 'Common'), 3, TRUE, '/assets/cards/lorcana_en_set2_15_89dd8994653f97f0b4be02f5b65b47c38259c01d.avif', '<p>&lt;Support&gt; (Whenever this character quests, you may add their {S} to another chosen character''s {S} this turn.)</p>', '15/204 EN 2', 'characters', 'Everything looks better when you’re free to be yourself.', 'Amber Kommavongsa'),
('Mulan', 'LC-232', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Rare'), 4, TRUE, '/assets/cards/lorcana_en_set2_16_68466fe0c384c87289f2d5f7375625fe255c7058.avif', '<p>&lt;Shift&gt; 2 (You may pay 2 {I} to play this on top of one of your characters named Mulan.)</p><p>\Honor to the Ancestors\ Whenever this character quests, you may reveal the top card of your deck. If it''s a song card, you may play it for free. Otherwise, put it on the top of your deck.</p>', '16/204 EN 2', 'characters', '', 'Lissette Carrera'),
('Nana', 'LC-233', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 2, TRUE, '/assets/cards/lorcana_en_set2_17_263a88acd583cd2b711d1181e8e779bd61df9da1.avif', '<p>\Nursemaid\ Whenever you play a Floodborn character, you may remove all damage from chosen character.</p>', '17/204 EN 2', 'characters', 'Children are a dog’s best friend.', 'Filipe Laurentino'),
('Piglet', 'LC-234', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Gateway'), (SELECT id FROM rarities WHERE name = 'Common'), 3, TRUE, '/assets/cards/lorcana_en_set2_18_b73dd2a611339891b044050ad20b0ddb7a3dc6b9.avif', '', '18/204 EN 2', 'characters', 'For a very small animal, he has an awfully big heart.', 'Kiersten Hale'),
('Rapunzel', 'LC-235', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 5, TRUE, '/assets/cards/lorcana_en_set2_19_30ae3a03247f0adc08d06e153678998c3a9c38ab.avif', '<p>&lt;Shift&gt; 3 (You may pay 3 {I} to play this on top of one of your characters named Rapunzel.)</p><p>\Let Your Power Shine\ Whenever you remove 1 or more damage from one of your characters, you may draw a card.</p>', '19/204 EN 2', 'characters', '', 'Aubrey Archer'),
('Rapunzel', 'LC-236', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Deep Trouble – Illumineer''s Quest'), (SELECT id FROM rarities WHERE name = 'Common'), 2, TRUE, '/assets/cards/lorcana_en_set2_20_99e629b7a21c93a626a46745ac21eb098a4b09f6.avif', '<p>\Magic Hair\ {E} — Remove up to 2 damage from chosen character.</p>', '20/204 EN 2', 'characters', '“We can all make the world a little brighter in our own way.”', 'Aubrey Archer'),
('Sleepy', 'LC-237', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 2, TRUE, '/assets/cards/lorcana_en_set2_21_fa3773856f8edc5e07083861a985143df282504a.avif', '<p>\Yawn!\ This character enters play exerted.</p>', '21/204 EN 2', 'characters', 'He never gets tired of naps.', 'Kendall Hale'),
('Sneezy', 'LC-238', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 2, TRUE, '/assets/cards/lorcana_en_set2_22_1499ef8e75015af2a54f9c27149a87107f1f8604.avif', '<p>Ah-choo!\ Whenever you play this character or another Seven Dwarfs character, you may give chosen character -1 {S} this turn.</p>', '22/204 EN 2', 'characters', 'Look out! He’s gonna blow!', 'Kendall Hale'),
('Snow White', 'LC-239', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 2, TRUE, '/assets/cards/lorcana_en_set2_23_b98739364096f2d5019964de940321811127be63.avif', '<p>\I Won''t Hurt You\ When you play this character, you may remove up to 2 damage from chosen character.</p>', '23/204 EN 2', 'characters', '“Why, you’re all alone, just like me.”', 'LadyShalirin'),
('Snow White', 'LC-240', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 2, FALSE, '/assets/cards/lorcana_en_set2_24_829a16daa1e8667b756d2758cddb40177c388c9a.avif', '<p>How Do You Do?\ You pay 1 {I} less to play Seven Dwarfs characters.</p>', '24/204 EN 2', 'characters', '“Nothing says ‘hello’ better than a fresh-baked pie.”', 'Samanta Erdini'),
('Snow White', 'LC-241', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Legendary'), 6, FALSE, '/assets/cards/lorcana_en_set2_25_11baea249412899001bf51f07ae2a89bb887074f.avif', '<p>&lt;Shift&gt; 4 (You may pay 4 {I} to play this on top of one of your characters named Snow White.)</p><p>\Wishes Come True\ Whenever this character quests, you may return a character card from your discard to your hand.</p>', '25/204 EN 2', 'characters', '', 'Javi Salas'),
('The Queen', 'LC-242', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Super Rare'), 5, TRUE, '/assets/cards/lorcana_en_set2_26_a17f0ac16d611d07a05c72c0af7710da6b6b0710.avif', '<p>&lt;Shift&gt; 2 (You may pay 2 {I} to play this on top of one of your characters named The Queen.)</p><p>\Who is the Fairest?\ Whenever this character quests, chosen opposing character gets -4 {S} this turn and chosen character gets +4 {S} this turn.</p>', '26/204 EN 2', 'characters', '', 'Matthew Robert Davies / LadyShalirin'),
('The Queen', 'LC-243', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 1, TRUE, '/assets/cards/lorcana_en_set2_27_0f4b8cb575f4c1733c10e9e508bfb3f58395513b.avif', '', '27/204 EN 2', 'characters', 'Don’t question her. Don’t doubt her. And above all, don’t disobey her.', 'Eva Widermann'),
('Hold Still', 'LC-244', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 2, TRUE, '/assets/cards/lorcana_en_set2_28_ca2024b84ad729c2a6dd9fc9f538101ae51b9579.avif', '<p>Remove up to 4 damage from chosen character.</p>', '28/204 EN 2', 'actions', '"This might sting a little."', 'Connie Kang / Jackie Droujko'),
('Last Stand', 'LC-245', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 2, FALSE, '/assets/cards/lorcana_en_set2_29_64214562013962df5cf428c6dabd9f170c25a0b0.avif', '<p>Banish chosen character who was challenged this turn.</p>', '29/204 EN 2', 'actions', '“Let’s finish this, binturi.” 
—Namaari', 'Aisha Durmagambetova'),
('Painting the Roses Red', 'LC-246', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 2, TRUE, '/assets/cards/lorcana_en_set2_30_ab65e3d241f9c637ba30f84039fccc3539f37196.avif', '<p>(A character with cost 2 or more can {E} to sing this song for free.)</p><p>Up to 2 chosen characters get -1 {S} this turn. Draw a card.</p>', '30/204 EN 2', 'actions', '', 'Matt Chapman'),
('World''s Greatest Criminal Mind', 'LC-247', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Gateway'), (SELECT id FROM rarities WHERE name = 'Rare'), 3, TRUE, '/assets/cards/lorcana_en_set2_31_236198576f6839b76352fd19785040bbe1b710c4.avif', '<p>(A character with cost 3 or more can {E} to sing this song for free.)</p><p>Banish chosen character with 5 {S} or more.</p>', '31/204 EN 2', 'actions', '', 'Giulia Riva'),
('Zero to Hero', 'LC-248', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 2, FALSE, '/assets/cards/lorcana_en_set2_32_38f613d097eb45a5e02c2f08de21f28f6cb8590a.avif', '<p>(A character with cost 2 or more can {E} to sing this song for free.)</p><p>Count the number of characters you have in play. You pay that amount of {I} less for the next character you play this turn.</p>', '32/204 EN 2', 'actions', '', 'Rob Di Salvo'),
('Dragon Gem', 'LC-249', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Rare'), 3, FALSE, '/assets/cards/lorcana_en_set2_33_30216e373945bc7bcd69c2f2f109213bebdd8ebf.avif', '<p>\Bring Back to Life\ {E}, 3 {I} — Return a character card with &lt;Support&gt; from your discard to your hand.</p>', '33/204 EN 2', 'items', 'Hope shines in even the darkest situations.', 'Andrew Trabbold'),
('Sleepy''s Flute', 'LC-250', (SELECT id FROM inks WHERE name = 'Amber'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Rare'), 2, FALSE, '/assets/cards/lorcana_en_set2_34_3c28591b07ea14106f4e509bb98407d6bc642456.avif', '<p>\A Silly Song\ {E} — If you played a song this turn, gain 1 lore.</p>', '34/204 EN 2', 'items', '', 'Antonia Flechsig')
