INSERT INTO cards (name, code, ink_id, second_ink_id, set_id, rarity_id, cost, inkable, image_url, description_html, identifier, card_type, flavor, illustrator) VALUES
('Arthur', 'LC-251', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Super Rare'), 3, FALSE, '/assets/cards/lorcana_en_set2_35_f1070b51c39bf396102ea18febe469fe83e16888.avif', '<p>\Student\ Whenever this character quests, you may return another chosen character of yours to your hand to gain 2 lore.</p>', '35/204 EN 2', 'characters', '"Hmm . .  what spell should I try next?"', 'Jake Parker'),
('Blue Fairy', 'LC-252', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 2, TRUE, '/assets/cards/lorcana_en_set2_36_957b79cc93c3ec31924c3060721c0456c424b241.avif', '<p>&lt;Evasive&gt; (Only characters with Evasive can challenge this character.)</p><p>\Ethereal Glow\ Whenever you play a Floodborn character, you may draw a card.</p>', '36/204 EN 2', 'characters', '“To make Geppetto’s wish come true will be entirely up to you.” —Blue Fairy', 'Kiersten Hale'),
('Chip the Teacup', 'LC-253', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 1, TRUE, '/assets/cards/lorcana_en_set2_37_86dbdd595cb67514e3887afedea013ae19903e6d.avif', '', '37/204 EN 2', 'characters', '"Wanna see me do a trick?"', 'Aubrey Archer'),
('Dr. Facilier', 'LC-254', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 4, TRUE, '/assets/cards/lorcana_en_set2_38_f988db8b93ed572b998a220a1e778015fe6e31cf.avif', '<p>&lt;Evasive&gt; (Only characters with Evasive can challenge this character.)</p>', '38/204 EN 2', 'characters', '', 'Leonardo Giammichele'),
('Elsa', 'LC-255', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 4, TRUE, '/assets/cards/lorcana_en_set2_39_3a59998036034c46a27333c6d0bf53af7afc37cb.avif', '<p>&lt;Challenger&gt; +3 (While challenging, this character gets +3 {S}.)</p>', '39/204 EN 2', 'characters', 'The power of ice may not stop the flood, but it will help protect Lorcana.', 'Cristian Romero'),
('Fairy Godmother', 'LC-256', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 5, TRUE, '/assets/cards/lorcana_en_set2_40_58ba1b11e562eb85700eef7b43dfb000c2a9279e.avif', '', '40/204 EN 2', 'characters', '“Use a humdrum spell, and you’ll end up with humdrum magic. I like my magic to have something special!”', 'Hedvig Häggman-Sund'),
('Fairy Godmother', 'LC-257', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Legendary'), 5, TRUE, '/assets/cards/lorcana_en_set2_41_25df7c5293adc1a81fa2ff40d0edbe9242131098.avif', '<p>&lt;Shift&gt; 2 (You may pay 2 {I} to play this on top of one of your characters named Fairy Godmother.)</p><p>\Forget the Coach, Here''s a Sword\ Whenever this character quests, your characters gain &lt;Challenger&gt; +3 and "When this character is banished in a challenge, return this card to your hand" this turn. (They get +3 {S} while challenging.)</p>', '41/204 EN 2', 'characters', '', 'Filipe Laurentino'),
('Fairy Godmother', 'LC-258', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 3, TRUE, '/assets/cards/lorcana_en_set2_42_7fca1d4b9a052c7efac7ab6d6a0dacb379b7cf37.avif', '<p>\Just Leave It to Me\ Whenever you play a character named Cinderella, you may exert chosen character.</p>', '42/204 EN 2', 'characters', '“We’ll have to hurry, because even miracles take a little time.”', 'Matt Chapman'),
('HeiHei', 'LC-259', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 2, TRUE, '/assets/cards/lorcana_en_set2_43_a0e1347e87aa483b78636929cd9df481e4b681d1.avif', '<p>\He''s Back!\ When this character is banished in a challenge, return this card to your hand.</p>', '43/204 EN 2', 'characters', 'Power. Beauty. HeiHei.', 'Ellie Horie'),
('Jiminy Cricket', 'LC-260', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 2, TRUE, '/assets/cards/lorcana_en_set2_44_ed1a27f9d72aa0d4f2bceebb4948158d6af8dc86.avif', '<p>&lt;Evasive&gt; (Only characters with Evasive can challenge this character.)</p><p>\That Still, Small Voice\ When you play this character, if you have a character named Pinocchio in play, you may draw a card.</p>', '44/204 EN 2', 'characters', '"Say, that''s pretty swell."', 'Isaiah Mesq'),
('Kuzco', 'LC-261', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 2, TRUE, '/assets/cards/lorcana_en_set2_45_de3758996782b848138cc2ba074f458db2bbff97.avif', '<p>\Ok, Where am I?\ When this character is banished, you may draw a card.</p>', '45/204 EN 2', 'characters', '"So there I was. Perfectly in control of the situation."', 'Michaela Martin'),
('Madam Mim', 'LC-262', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Gateway'), (SELECT id FROM rarities WHERE name = 'Rare'), 3, TRUE, '/assets/cards/lorcana_en_set2_46_8354c3301599007bcad27e4cecc956bd4d7e8e2d.avif', '<p>\Chasing the Rabbit\ When you play this character, banish her or return another chosen character of yours to your hand.</p><p>&lt;Rush&gt; (This character can challenge the turn they''re played.)</p>', '46/204 EN 2', 'characters', '', 'Alice Pisoni'),
('Madam Mim', 'LC-263', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Legendary'), 7, TRUE, '/assets/cards/lorcana_en_set2_47_9f2dcb7d72cd4b37acb394c49d1594701463c35a.avif', '<p>&lt;Evasive&gt; (Only characters with Evasive can challenge this character.)</p><p>\I Win, I Win!\ When you play this character, banish her or return another 2 chosen characters of yours to your hand.</p>', '47/204 EN 2', 'characters', '"Did I say no purple dragons? Did I?"', 'Ally Zermeno'),
('Madam Mim', 'LC-264', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Gateway'), (SELECT id FROM rarities WHERE name = 'Rare'), 5, TRUE, '/assets/cards/lorcana_en_set2_48_f97f3d5bb1dc92f65d5f2bbc459add3a048d5541.avif', '<p>&lt;Shift&gt; 3 (You may pay 3 {I} to play this on top of one of your characters named Madam Mim.)</p><p>\Gruesome and Grim\ {E} — Play a character with cost 4 or less for free. They gain &lt;Rush&gt;. At the end of the turn, banish them. (They can challenge the turn they''re played.)</p>', '48/204 EN 2', 'characters', '', 'Mané Kandalyan / Pix Smith'),
('Madam Mim', 'LC-265', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Gateway'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 2, TRUE, '/assets/cards/lorcana_en_set2_49_1f5e61f678f6cc5e08b780f7c39d26d995989772.avif', '<p>\Just You Wait\ When you play this character, banish her or return another chosen character of yours to your hand.</p>', '49/204 EN 2', 'characters', '“I’ve got you rattled now!”', 'Brian Weisz'),
('Merlin', 'LC-266', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Common'), 3, TRUE, '/assets/cards/lorcana_en_set2_50_64808ffe282196d4f4cb06e8bc04046a2bf16373.avif', '<p>\Ready or Not!\ When you play this character and when he leaves play, chosen character gains &lt;Challenger&gt; +3 this turn. (They get +3 {S} while challenging.)</p>', '50/204 EN 2', 'characters', 'He’ll be out of this in a snap!', 'Valentina Graziuso'),
('Merlin', 'LC-267', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Rise of the Floodborn'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 4, TRUE, '/assets/cards/lorcana_en_set2_51_7d977eefd791bc8c448fdbfa607e58b53688d1bb.avif', '<p>\Here I Come!\ When you play this character and when he leaves play, gain 1 lore.</p>', '51/204 EN 2', 'characters', '"He always was a stubborn old goat."%—Madam Mim', 'S. Shaw / L. Giammichele'),
('Merlin', 'LC-268', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Gateway'), (SELECT id FROM rarities WHERE name = 'Rare'), 4, FALSE, '/assets/cards/lorcana_en_set2_52_40161ef659387e7a361ffc7b69c03bfc9a98856a.avif', '<p>\Hoppity Hip!\ When you play this character and when he leaves play, you may draw a card.</p>', '52/204 EN 2', 'characters', 'It was turning out to be a bad hare day.', 'Michaela Martin'),
