('Iago', 'LC-1244', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Azurite Sea'), (SELECT id FROM rarities WHERE name = 'Common'), 4, TRUE, '/assets/cards/lorcana_en_set6_45_c71e8dc7133bce037f04153fc5f096c5cec2f34c.avif', '<p>\Guess Who\ When this character is banished in a challenge, return this card to your hand.</p>', '45/204 EN 6', 'characters', '"You think you can get rid of me <that> easy?!"', 'Cam Kendell'),
