INSERT INTO cards (name, code, ink_id, second_ink_id, set_id, rarity_id, cost, inkable, image_url, description_html, identifier, card_type, flavor, illustrator) VALUES
('Sisu', 'LC-1253', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Azurite Sea'), (SELECT id FROM rarities WHERE name = 'Super Rare'), 4, FALSE, '/assets/cards/lorcana_en_set6_54_3b6de9866ec87dac17ed2234c9e8e3aa248faf67.avif', '<p>\Trust Builds Trust\ Whenever this character quests, reveal the top card of your deck. If it''s a Dragon character card, put it into your hand and repeat this effect. Otherwise, put it on either the top or the bottom of your deck.</p>', '54/204 EN 6', 'characters', '', 'Shannon Hallstein'),
