('Archimedes', 'LC-1509', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Archazia’s Island'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 2, TRUE, '/assets/cards/lorcana_en_set7_76_d8de52733a8054a9f1829b6eebbbfbb3437a031a.avif', '<p>\More to Learn\ Whenever an opponent chooses this character for an action or ability, you may draw a card.</p>', '76/204 EN 7', 'characters', 'Archazia’s library was a treasure trove of knowledge even for such an educated owl.', 'Luis Huerta'),
('Kashekim', 'LC-1510', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Archazia’s Island'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 3, TRUE, '/assets/cards/lorcana_en_set7_77_d25005b71288b680117aaae6405bc5ae87f0588b.avif', '', '77/204 EN 7', 'characters', '"You presume much, to think you are welcome here."', 'Jocelyn Sepulveda'),
