('Grimorum Arcanorum', 'LC-2256', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Whispers in the Well'), (SELECT id FROM rarities WHERE name = 'Rare'), 3, TRUE, '/assets/cards/lorcana_en_set10_67_82a2fcee7e949bc292fc98606bf14961e16f2bcd.jpg', '<p>\Doctrina Adducere\ During your turn, whenever an opposing character becomes exerted, gain 1 lore.</p><p>\Celeritas\ Your characters named Demona gain &lt;Rush&gt;. (They can challenge the turn they''re played.)</p>', '67/204 EN 10', 'items', '', 'Irish Chua'),
('The Great Illuminary', 'LC-2257', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Whispers in the Well'), (SELECT id FROM rarities WHERE name = 'Uncommon'), 2, TRUE, '/assets/cards/lorcana_en_set10_68_a50f12321fcf05a2d15ea5f8e37e8715083a3d65.jpg', '<p>\Startling Discovery\ Characters gain "{E} — Draw a card" while here.</p>', '68/204 EN 10', 'locations', '“Remember, we’re looking for clues to who tore up the lorebook pages.”
—Elisa Maza', 'Priya Kakati'),
('Baloo', 'LC-2258', (SELECT id FROM inks WHERE name = 'Emerald'), NULL, (SELECT id FROM card_sets WHERE name = 'Whispers in the Well'), (SELECT id FROM rarities WHERE name = 'Common'), 2, TRUE, '/assets/cards/lorcana_en_set10_69_b75eea83c409fc60b89a487ab562d5129c558f47.avif', '', '69/204 EN 10', 'characters', '"I tell ya, for a spooky forest, this place is all right. Plenty of berries, lots of trees for back-scratching . . .  A bear could do a lot worse."', 'Laura Pauselli'),
('Big Nose', 'LC-2259', (SELECT id FROM inks WHERE name = 'Emerald'), NULL, (SELECT id FROM card_sets WHERE name = 'Whispers in the Well'), (SELECT id FROM rarities WHERE name = 'Common'), 1, TRUE, '/assets/cards/lorcana_en_set10_70_3035b1bd85c5820ee7723035b52b834f90aa00b3.avif', '', '70/204 EN 10', 'characters', '"Thou art pretty as a brawl
Thy hair''s as dark as a moonless night
Thy cheeks the red of leaves in fall—
I love to sit and watch you fight"', 'Jochem Van Gool'),
('Flotsam', 'LC-2260', (SELECT id FROM inks WHERE name = 'Emerald'), NULL, (SELECT id FROM card_sets WHERE name = 'Whispers in the Well'), (SELECT id FROM rarities WHERE name = 'Common'), 3, TRUE, '/assets/cards/lorcana_en_set10_71_fcd84d78e692826344348895cbc360025ee5a75a.avif', '<p>&lt;Evasive&gt; (Only characters with Evasive can challenge this character.)</p>', '71/204 EN 10', 'characters', '"You''re in our world now."', 'Ricardo Caria'),
('Kaa', 'LC-2261', (SELECT id FROM inks WHERE name = 'Emerald'), NULL, (SELECT id FROM card_sets WHERE name = 'Whispers in the Well'), (SELECT id FROM rarities WHERE name = 'Common'), 3, TRUE, '/assets/cards/lorcana_en_set10_72_994e836a47868ce98e271cfee3d0b8323082643a.avif', '<p>&lt;Ward&gt; (Opponents can''t choose this character except to challenge.)</p>', '72/204 EN 10', 'characters', '"It''s bessst to play it s-ssafe."', 'Sergio Mancinelli'),
('Webby Vanderquack', 'LC-2262', (SELECT id FROM inks WHERE name = 'Emerald'), NULL, (SELECT id FROM card_sets WHERE name = 'Whispers in the Well'), (SELECT id FROM rarities WHERE name = 'Common'), 1, TRUE, '/assets/cards/lorcana_en_set10_73_dcd0fd3ccc2fe58466ba74f81bfa38d55b7640f5.avif', '<p>\Contagious Energy\ When you play this character, chosen character gets +1 {S} this turn.</p>', '73/204 EN 10', 'characters', '“It’s happening! IT’S HAPPENING! There''s a whisper nearby, and I get to see it!"', 'Rosa la Barbera / Livio Cacciatore'),
('Finnick', 'LC-2263', (SELECT id FROM inks WHERE name = 'Emerald'), NULL, (SELECT id FROM card_sets WHERE name = 'Whispers in the Well'), (SELECT id FROM rarities WHERE name = 'Common'), 1, TRUE, '/assets/cards/lorcana_en_set10_74_1a416ccee8a368953e5f9241496f829fb714236f.avif', '<p>\You Better Run\ When you play this character, you may pay 2 {I} to return chosen opposing character with 2 {S} or less to their player''s hand.</p>', '74/204 EN 10', 'characters', '', 'Mario Oscar Gabriele'),
