('Fflewddur Fflam', 'LC-3009', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Attack of the Vine!'), (SELECT id FROM rarities WHERE name = 'Common'), 6, TRUE, '/assets/cards/lorcana_en_set13_38_7a646f6053b11a5a32211f5167d565e5d28aceae.avif', '<p>\Chasing Adventure\ When you play this character, if a character of yours quested this turn, draw a card.</p>', '38/207 EN 13', 'characters', '"Well, now, I can''t say this was unexpected. But still, if you could just set me down gently . . ."', 'Brian Kesinger'),
('Maleficent', 'LC-3010', (SELECT id FROM inks WHERE name = 'Amethyst'), NULL, (SELECT id FROM card_sets WHERE name = 'Attack of the Vine!'), (SELECT id FROM rarities WHERE name = 'Common'), 1, TRUE, '/assets/cards/lorcana_en_set13_39_2ebcb1d2d772108f3869e8f9c21f20767fbece63.avif', '', '39/207 EN 13', 'characters', '"Such destruction! Look around—vines as far as the eye can see. And here we sit, at the heart of it."', 'Ornella Savarese'),
